const row = $json;
const text = (value) => value == null ? '' : String(value).trim();
const uuid = () => 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, (c) => {
  const r = Math.floor(Math.random() * 16);
  return (c === 'x' ? r : ((r & 3) | 8)).toString(16);
});

const status = text(row['Processing Status']).toLowerCase();
const operation = text(row['Operation']);
const formResponseId = text(row['Form Response ID']);
const retryCountValue = Number(row['Retry Count'] || 0);

const queue = {
  formResponseId,
  retryCount: Number.isFinite(retryCountValue) ? retryCountValue : 0,
  incomingStatus: status,
  operation,
};

const processable = status === 'pending' && operation === 'student.profile.submit';

if (!processable) {
  return {
    json: {
      processable: false,
      queue,
      skipReason: status !== 'pending'
        ? 'QUEUE_ROW_NOT_PENDING'
        : 'QUEUE_OPERATION_MISMATCH',
    },
  };
}

if (!formResponseId) throw new Error('VALIDATION_FORM_RESPONSE_ID_REQUIRED');

let raw = row['Raw Response JSON'];
if (typeof raw === 'string') {
  try {
    raw = JSON.parse(raw);
  } catch {
    throw new Error('VALIDATION_RAW_RESPONSE_JSON');
  }
}

if (!raw || typeof raw !== 'object' || Array.isArray(raw)) {
  throw new Error('VALIDATION_RAW_RESPONSE_OBJECT');
}

const get = (title) => text(raw[title]);
const lines = get('Required document Drive links (one per line)')
  .split(/\r?\n/)
  .map((value) => value.trim())
  .filter(Boolean);

const documents = lines.map((line) => {
  const separator = line.indexOf('|');
  if (separator < 0) return { document_code: null, url: line };
  return {
    document_code: line.slice(0, separator).trim().toUpperCase(),
    url: line.slice(separator + 1).trim(),
  };
});

const correlationId = uuid();
const idempotencyKey =
  text(row['Idempotency Key']) ||
  `google-form:${text(row['Source Form ID'])}:${formResponseId}`;
const submittedAt = text(row['Submitted At UTC']) || new Date().toISOString();

const request = {
  operation: 'student.profile.submit',
  correlation_id: correlationId,
  idempotency_key: idempotencyKey,
  requester: {
    email: text(row['Respondent Email']),
    type: 'google_form_respondent',
  },
  submitted_at: submittedAt,
  source: {
    channel: 'google_forms',
    source_submission_id: formResponseId,
    source_form_id: text(row['Source Form ID']),
    source_spreadsheet_id: text(row['Source Spreadsheet ID']),
  },
  payload: {
    institution_code: get('Institution code'),
    campus_code: get('Campus code'),
    submission_type: get('Submission type'),
    student_number: get('Student number (leave blank only for a new admission)'),
    full_name: get('Full legal name'),
    date_of_birth: get('Date of birth'),
    gender: get('Gender'),
    primary_email: get('Primary email address'),
    mobile_phone: get('Mobile phone number'),
    guardian_name: get('Guardian name (required for school students)'),
    guardian_phone: get('Guardian phone (required for school students)'),
    identity_reference: get('Institution-approved identity reference'),
    program_code: get('Program or qualification code'),
    academic_year_code: get('Academic year code'),
    admission_term_code: get('Admission term code'),
    previous_qualification: get('Previous qualification or school'),
    documents,
    additional_notes: get('Additional notes'),
    submitted_on: submittedAt.slice(0, 10),
  },
};

return { json: { processable: true, queue, request } };

const source = $('Normalize Student Queue Row').item.json;
const raw = $json ?? {};

let body = Object.prototype.hasOwnProperty.call(raw, 'body') ? raw.body : raw;

if (typeof body === 'string') {
  try {
    body = JSON.parse(body);
  } catch {
    body = { message: body };
  }
}

if (Array.isArray(body) && body.length === 1 && body[0] && typeof body[0] === 'object') {
  body = body[0];
}

const statusValue = raw.statusCode ?? raw.status ?? null;
const statusCode = statusValue == null
  ? (raw.error ? 0 : 200)
  : Number(statusValue);

const transportError =
  typeof raw.error === 'string'
    ? raw.error
    : (raw.error?.message || raw.message || '');

const bodyError =
  body && typeof body === 'object'
    ? (body.error && typeof body.error === 'object' ? body.error : body)
    : {};

const rpcSuccess =
  statusCode >= 200 &&
  statusCode < 300 &&
  body &&
  typeof body === 'object' &&
  body.success === true;

const errorCode = rpcSuccess
  ? ''
  : String(
      bodyError.code ||
      bodyError.error_code ||
      (statusCode > 0 ? `HTTP_${statusCode}` : 'NETWORK_FAILURE')
    ).slice(0, 100);

const errorMessage = rpcSuccess
  ? ''
  : String(
      bodyError.message ||
      bodyError.error_message ||
      transportError ||
      'The operation could not be completed.'
    ).slice(0, 300);

const now = new Date().toISOString();

return {
  json: {
    'Form Response ID': source.queue.formResponseId,
    'Processing Status': rpcSuccess ? 'completed' : 'failed',
    'Processed At UTC': now,
    'Correlation ID': body?.correlation_id || source.request.correlation_id,
    'Error Code': errorCode,
    'Error Message': errorMessage,
    'Retry Count': source.queue.retryCount + (rpcSuccess ? 0 : 1),
    'Last Attempt At UTC': now,
    'n8n Execution ID': $execution.id,
    rpcResult: body,
    httpStatusCode: statusCode,
    success: rpcSuccess,
  },
};
